param([string]$ProjectPath='C:\xampp\htdocs\landing-page-felippe')
$ErrorActionPreference='Stop'
$target=(Resolve-Path -LiteralPath $ProjectPath).Path
if(!(Test-Path -LiteralPath (Join-Path $target 'builder-api.php'))){throw 'Pasta de projeto incorreta.'}
$files=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')) | ConvertFrom-Json
# Validate every source before touching any file. Never overwrite later user edits.
foreach($file in $files){
 $path=[IO.Path]::GetFullPath((Join-Path $target $file.path))
 if(!$path.StartsWith($target.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Caminho invalido.'}
 if((Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $file.sha){throw "Arquivo alterado desde a preparacao: $($file.path). Nenhum arquivo foi substituido."}
}
$backup=Join-Path $target ('backup-infinityfree-'+[DateTime]::Now.ToString('yyyyMMdd-HHmmss-ffff'))
New-Item -ItemType Directory -Path $backup | Out-Null
$utf8=New-Object Text.UTF8Encoding($false)
foreach($file in $files){
 $old=Join-Path $target $file.path
 $copy=Join-Path $backup $file.path
 New-Item -ItemType Directory -Force -Path (Split-Path -Parent $copy) | Out-Null
 Copy-Item -LiteralPath $old -Destination $copy
}
$envPath=Join-Path $target '.env'
if(Test-Path -LiteralPath $envPath){Copy-Item -LiteralPath $envPath -Destination (Join-Path $backup '.env')}
foreach($file in $files){[IO.File]::WriteAllBytes((Join-Path $target $file.path),[Convert]::FromBase64String($file.data))}
$envText=if(Test-Path -LiteralPath $envPath){[IO.File]::ReadAllText($envPath)}else{''}
function Set-EnvEntry([string]$name,[string]$value,[bool]$preserve=$false){
 $pattern='(?m)^'+[regex]::Escape($name)+'=.*$'
 if([regex]::IsMatch($script:envText,$pattern)){
  if(!$preserve){$script:envText=[regex]::Replace($script:envText,$pattern,($name+'='+$value))}
 }else{$script:envText+="`r`n$name=$value`r`n"}
}
Set-EnvEntry 'BUILDER_ENABLED' '0'
Set-EnvEntry 'BUILDER_HOSTING_MODE' 'infinityfree'
Set-EnvEntry 'BUILDER_BASE_URL' 'https://felippeandreatadev.page.gd' $true
Set-EnvEntry 'BUILDER_CONTACT_EMAIL' 'felippefardin@gmail.com' $true
Set-EnvEntry 'MP_MODE' 'test'
if($envText -notmatch '(?m)^BUILDER_APP_KEY=.+$'){
 $keyBytes=New-Object byte[] 32
 $rng=[Security.Cryptography.RandomNumberGenerator]::Create()
 try{$rng.GetBytes($keyBytes)}finally{$rng.Dispose()}
 Set-EnvEntry 'BUILDER_APP_KEY' ([BitConverter]::ToString($keyBytes).Replace('-','').ToLowerInvariant())
}
[IO.File]::WriteAllText($envPath,$envText,$utf8)
Write-Host 'Adaptacao aplicada. Compras continuam desativadas ate testar API, banco e e-mail.'
Write-Host "Backup: $backup"
Write-Host 'Publique os arquivos alterados e configure o .env da hospedagem sem sobrescrever banco/SMTP.'
